searchDatas1[40] = ['','Outil de sélection du scanneur','./tb_select.html', '	Outil de sélection du scanneur	Cette section décrit les messages d\'erreur susceptibles de s\'afficher lors de l\'utilisation de l\'Outil de sélection du scanneur, et explique comment résoudre ces erreurs. 	Échec de la modification du fichier de configuration.	Échec du traitement suite à une erreur inattendue.	Adresse IP non valide. Saisissez une adresse IP correcte.	Échec du chargement du fichier de configuration.	Impossible de démarrer le programme.	Aucun fichier d\'aide trouvé.	Le nom est incorrect. Saisissez le nom correct.	'];
searchDatas1[41] = ['','Échec de la modification du fichier de configuration.','./tb_select_01.html', '	Échec de la modification du fichier de configuration.	Cause 	Les origines du problème peuvent être les suivantes :	Il est impossible de créer un fichier de configuration ou d\'écrire sur un fichier de configuration	Échec de l\'obtention du chemin d\'accès au fichier de configuration	Une autre application accède au fichier de configuration	Solution 	Quittez toutes les applications en cours d\'exécution, puis redémarrez l\'Outil de sélection du scanneur.'];
searchDatas1[42] = ['','Échec du traitement suite à une erreur inattendue.','./tb_select_03.html', '	Échec du traitement suite à une erreur inattendue.	Cause 	Une erreur inattendue est survenue.	Solution 	Redémarrez l\'ordinateur, puis redémarrez l\'Outil de sélection du scanneur.'];
searchDatas1[43] = ['','Adresse IP non valide. Saisissez une adresse IP correcte.','./tb_select_04.html', '	Adresse IP non valide. Saisissez une adresse IP correcte.	Cause 	L\'adresse IP que vous avez saisie est incorrecte.	Solution 	Pour fi-8040 ou fi-7300NX	Vérifiez l\'adresse IP sur l\'écran tactile du scanneur, puis saisissez l\'adresse IP correcte.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.	Pour fi-8950, fi-8930, fi-8820, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150 ou fi-8250	Utilisez l\'Outil de configuration de l\'adresse IP pour vérifier l\'adresse IP du scanneur et saisissez l\'adresse IP correcte.	Pour en savoir plus sur la façon de démarrer l\'Outil de configuration de l\'adresse IP, consultez la section 	Démarrage de l\'Outil de configuration de l\'adresse IP.'];
searchDatas1[44] = ['','Échec du chargement du fichier de configuration.','./tb_select_05.html', '	Échec du chargement du fichier de configuration.	Cause 	Les origines du problème peuvent être les suivantes :	Vous ne disposez pas de privilèges d\'accès au fichier de configuration	Échec de l\'obtention du chemin d\'accès au fichier de configuration	Une autre application accède au fichier de configuration	Solution 	Quittez toutes les applications en cours d\'exécution, puis redémarrez l\'Outil de sélection du scanneur.'];
searchDatas1[45] = ['','Impossible de démarrer le programme.','./tb_select_06.html', '	Impossible de démarrer le programme.	Cause 	Les origines du problème peuvent être les suivantes :	Une erreur est survenue sur l\'ordinateur	Il n\'existe aucun fichier exécutable pour l\'Outil de configuration de l\'adresse IP	Solution 	Procédez comme suit :	Redémarrez le scanneur.	Désinstallez l\'application Network Setup Tool for fi Series, puis réinstallez-la.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.'];
searchDatas1[46] = ['','Aucun fichier d\'aide trouvé.','./tb_select_07.html', '	Aucun fichier d\'aide trouvé.	Cause 	Le fichier d\'aide n\'existe pas.	Solution 	Désinstallez l\'application Network Setup Tool for fi Series, puis réinstallez-la.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.'];
searchDatas1[47] = ['','Le nom est incorrect. Saisissez le nom correct.','./tb_select_08.html', '	Le nom est incorrect. Saisissez le nom correct.	Cause 	Le nom du scanner est incorrect.	Solution 	Saisissez le nom correct.	Les caractères suivants sont disponibles :	Caractères alphanumériques	- (tiret)	. (Période)	Il est possible de saisir jusqu\'à 255 caractères.'];
searchDatas1[48] = ['','Outil de configuration de l\'adresse IP','./tb_ip.html', '	Outil de configuration de l\'adresse IP	Cette section décrit les messages d\'erreur susceptibles de s\'afficher lors de l\'utilisation de l\'Outil de configuration de l\'adresse IP, et explique comment résoudre ces erreurs. 	Connectez le scanneur à l\'ordinateur à l\'aide du câble USB.	Connectez uniquement un scanneur.	Une erreur de communication s\'est produite.	Des caractères non pris en charge sont inclus dans le nom du scanneur.	Une adresse réservée ne peut pas être spécifiée pour l\'adresse IP.	Une adresse réservée ne peut pas être spécifiée pour le masque de sous-réseau.	L\'adresse IP ou le masque de sous-réseau n\'est pas valide.	Le format de l\'adresse IP est incorrect.	Le format de la longueur du préfixe de sous-réseau est incorrect.	Une adresse réservée ne peut pas être spécifiée pour la passerelle par défaut.	Le format de la passerelle par défaut est incorrect.	La passerelle par défaut ou le masque de sous-réseau n\'est pas valide.	Aucun nom de scanner n\'a été saisi.	Ce scanneur est utilisé par un autre utilisateur ou une autre application.	Impossible de démarrer le programme.	La connexion a échoué.	Aucun fichier d\'aide trouvé.	'];
searchDatas1[49] = ['','Connectez le scanneur à l\'ordinateur à l\'aide du câble USB.','./tb_ip_01.html', '	Connectez le scanneur à l\'ordinateur à l\'aide du câble USB.	Cause 	Les origines du problème peuvent être les suivantes :	Le scanneur n\'est pas connecté à l\'ordinateur avec le câble USB	Le pilote du scanneur n\'a pas été installé	Le scanneur est éteint	Le scanneur connecté à l\'ordinateur n\'est pas pris en charge par l\'Outil de configuration de l\'adresse IP	Solution 	Procédez comme suit :	Reliez le scanneur à l\'ordinateur à l\'aide du câble USB fourni avec le scanneur.	Installez le pilote du scanneur.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.	Mettez le scanneur sous tension.	Vérifiez les modèles de scanneurs pris en charge par l\'Outil de configuration de l\'adresse IP.	Pour en savoir plus, reportez-vous à la rubrique 	Modèles de scanneurs pris en charge.'];
searchDatas1[50] = ['','Connectez uniquement un scanneur.','./tb_ip_02.html', '	Connectez uniquement un scanneur.	Cause 	Plusieurs scanneurs sont connectés à l\'ordinateur.	Solution 	Connectez un seul scanneur à l\'ordinateur à l\'aide d\'un câble USB.'];
searchDatas1[51] = ['','Une erreur de communication s\'est produite.','./tb_ip_03.html', '	Une erreur de communication s\'est produite.	Cause 	Les origines du problème peuvent être les suivantes :	Une erreur s\'est produite lors de la connexion avec le scanneur	Une opération a été exécutée alors que le scanneur était en cours d\'initialisation	La fonction réseau du scanner est désactivée 	Solution 	Procédez comme suit :	Redémarrez le scanneur.	Vérifiez que l\'initialisation du scanneur est terminée.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.	Démarrez le Software Operation Panel pour activer la fonction réseau.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.'];
searchDatas1[52] = ['','Des caractères non pris en charge sont inclus dans le nom du scanneur.','./tb_ip_04.html', '	Des caractères non pris en charge sont inclus dans le nom du scanneur.	Cause 	Des caractères non compatibles avec le nom du scanneur ont été utilisés.	Solution 	Vérifiez les caractères utilisés pour le nom du scanneur.	Les caractères autorisés sont les suivants : caractères alphanumériques, "-" (tiret), "_" (trait de soulignement) et espaces.'];
searchDatas1[53] = ['','Une adresse réservée ne peut pas être spécifiée pour l\'adresse IP.','./tb_ip_05.html', '	Une adresse réservée ne peut pas être spécifiée pour l\'adresse IP.	Cause 	Une adresse IP non valide a été définie.	Solution 	Saisissez une adresse IP correcte.	Pour une adresse IPv4	Chaque xxx dans xxx.xxx.xxx.xxx doit correspondre à une valeur comprise entre 0 et 255.	Vérifiez les éléments suivants et réessayez.	Les valeurs que vous avez saisies sont identiques à celles attribuées au scanneur	Pour une adresse IPv6	Chaque xxxx dans xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx doit être une valeur comprise entre 0 et ffff.	Vérifiez les éléments suivants et réessayez.	Les valeurs que vous avez saisies sont identiques à celles attribuées au scanneur'];
searchDatas1[54] = ['','Une adresse réservée ne peut pas être spécifiée pour le masque de sous-réseau.','./tb_ip_06.html', '	Une adresse réservée ne peut pas être spécifiée pour le masque de sous-réseau.	Cause 	Un masque de sous réseau non valide a été défini.	Solution 	Saisissez une valeur de masque de sous réseau valide.	Chaque xxx dans xxx.xxx.xxx.xxx doit correspondre à une valeur comprise entre 0 et 255.	Vérifiez les éléments suivants et réessayez.	Les valeurs que vous avez saisies sont identiques à celles attribuées au masque de sous réseau'];
searchDatas1[55] = ['','L\'adresse IP ou le masque de sous-réseau n\'est pas valide.','./tb_ip_07.html', '	L\'adresse IP ou le masque de sous-réseau n\'est pas valide.	Cause 	Un masque de sous réseau ou une adresse IP non valide a été défini(e).	Solution 	Saisissez une adresse IP ou un masque de sous réseau valide.	Chaque xxx dans xxx.xxx.xxx.xxx doit correspondre à une valeur comprise entre 0 et 255.	Vérifiez que les valeurs que vous avez saisies sont identiques à celles attribuées au scanneur ou au masque de sous réseau, puis réessayez.'];
searchDatas1[56] = ['','Le format de l\'adresse IP est incorrect.','./tb_ip_18.html', '	Le format de l\'adresse IP est incorrect.	Cause 	Le format de l\'adresse IP pour IPv6 est incorrect.	Solution 	Saisissez l\'adresse IP dans le format correct.	Chaque xxxx dans xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx doit être une valeur comprise entre 0 et ffff.	Vérifiez les éléments suivants et réessayez.	Une valeur sous forme de nombre hexadécimal est saisie dans les champs de saisie.	Une forme abrégée (::) est utilisée moins de deux fois.	Aucun espace dans les champs de saisie'];
searchDatas1[57] = ['','Le format de la longueur du préfixe de sous-réseau est incorrect.','./tb_ip_16.html', '	Le format de la longueur du préfixe de sous-réseau est incorrect.	Cause 	La longueur du préfixe de sous-réseau pour l\'adresse IPv6 est incorrecte.	Solution 	Entrez la longueur du préfixe de sous-réseau dans le format correct.	Une valeur de 3 à 128 peut être saisie.'];
searchDatas1[58] = ['','Une adresse réservée ne peut pas être spécifiée pour la passerelle par défaut.','./tb_ip_09.html', '	Une adresse réservée ne peut pas être spécifiée pour la passerelle par défaut.	Cause 	Une passerelle par défaut non valide a été définie.	Solution 	Saisissez une passerelle par défaut valide.	Pour une adresse IPv4	Chaque xxx dans xxx.xxx.xxx.xxx doit correspondre à une valeur comprise entre 0 et 255.	Vérifiez les éléments suivants et réessayez.	Les valeurs que vous avez saisies sont identiques à celles attribuées à la passerelle par défaut	Pour une adresse IPv6	Chaque xxxx dans xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx doit être une valeur comprise entre 0 et ffff.	Vérifiez les éléments suivants et réessayez.	Les valeurs que vous avez saisies sont identiques à celles attribuées à la passerelle par défaut'];
searchDatas1[59] = ['','Le format de la passerelle par défaut est incorrect.','./tb_ip_19.html', '	Le format de la passerelle par défaut est incorrect.	Cause 	La passerelle par défaut pour IPv6 est dans un format incorrect.	Solution 	Saisissez la passerelle par défaut dans le format correct.	Chaque xxxx dans xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx doit être une valeur comprise entre 0 et ffff.	Vérifiez les éléments suivants et réessayez.	Une valeur sous forme de nombre hexadécimal est saisie dans les champs de saisie.	Une forme abrégée (::) est utilisée moins de deux fois.'];
searchDatas1[60] = ['','La passerelle par défaut ou le masque de sous-réseau n\'est pas valide.','./tb_ip_10.html', '	La passerelle par défaut ou le masque de sous-réseau n\'est pas valide.	Cause 	Un masque de sous réseau ou une passerelle par défaut non valide a été défini(e).	Solution 	Saisissez une passerelle par défaut ou un masque de sous réseau valide.	Chaque xxx dans xxx.xxx.xxx.xxx doit correspondre à une valeur comprise entre 0 et 255.	Vérifiez que les valeurs que vous avez saisies sont identiques à celles attribuées à la passerelle par défaut ou au masque de sous réseau, puis réessayez.'];
searchDatas1[61] = ['','Aucun nom de scanner n\'a été saisi.','./tb_ip_14.html', '	Aucun nom de scanner n\'a été saisi.	Cause 	Aucun nom de scanner n\'a été saisi.	Solution 	Saisissez au minimum un caractère dans le champ de saisie [Nom du scanneur].	Les caractères autorisés sont les suivants : caractères alphanumériques, "-" (tiret), "_" (trait de soulignement) et espaces.'];
searchDatas1[62] = ['','Ce scanneur est utilisé par un autre utilisateur ou une autre application.','./tb_ip_12.html', '	Ce scanneur est utilisé par un autre utilisateur ou une autre application.	Cause 	Une autre application ou un autre utilisateur utilise actuellement le scanneur.	Solution 	Vérifiez que l\'autre application ou l\'autre utilisateur n\'utilise pas le scanneur.	Quittez l\'application qui utilise actuellement le scanneur.	Si le problème persiste, éteignez le scanneur, puis rallumez-le.'];
searchDatas1[63] = ['','Impossible de démarrer le programme.','./tb_ip_13.html', '	Impossible de démarrer le programme.	Cause 	Les origines du problème peuvent être les suivantes :	Une erreur est survenue sur l\'ordinateur	Il n\'existe aucun fichier exécutable pour l\'Outil de sélection du scanneur	Solution 	Procédez comme suit :	Redémarrez le scanneur.	Désinstallez l\'application Network Setup Tool for fi Series, puis réinstallez-la.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.'];
searchDatas1[64] = ['','La connexion a échoué.','./tb_ip_17.html', '	La connexion a échoué.	Cause 	Les origines du problème peuvent être les suivantes :	Le mot de passe que vous avez saisi est différent du mot de passe de l\'administrateur du scanneur	Une erreur est survenue dans le scanneur	Solution 	Procédez comme suit :	Saisissez le mot de passe de l\'administrateur du scanneur correct.	Redémarrez le scanneur.'];
searchDatas1[65] = ['','Aucun fichier d\'aide trouvé.','./tb_ip_15.html', '	Aucun fichier d\'aide trouvé.	Cause 	Le fichier d\'aide n\'existe pas.	Solution 	Désinstallez l\'application Network Setup Tool for fi Series, puis réinstallez-la.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.'];
searchDatas1[66] = ['','Outil d\'enregistrement de certificats','./tb_cer.html', '	Outil d\'enregistrement de certificats	Cette section décrit les messages d\'erreur susceptibles de s\'afficher lors de l\'utilisation de l\'Outil d\'enregistrement de certificats, et explique comment résoudre ces erreurs. 	Échec de la connexion au scanneur.	Échec de l\'obtention des informations du certificat.	Échec de la suppression du certificat.	Échec de l\'enregistrement du certificat.	Mot de passe incorrect.	'];
searchDatas1[67] = ['','Échec de la connexion au scanneur.','./tb_cer_01.html', '	Échec de la connexion au scanneur.	Cause 	Les origines du problème peuvent être les suivantes :	Le scanneur est éteint	Le scanneur n\'est pas connecté à l\'ordinateur avec le câble USB	Le processus de démarrage est en cours sur le scanneur	Les paramètres du scanneur sont en cours de modification	Plusieurs scanneurs sont connectés à l\'ordinateur	Une autre application utilise actuellement le scanneur	Le scanneur connecté à l\'ordinateur n\'est pas pris en charge par l\'Outil d\'enregistrement de certificats	Solution 	Procédez comme suit :	Mettez le scanneur sous tension.	Reliez le scanneur à l\'ordinateur à l\'aide du câble USB fourni avec le scanneur.	Vérifiez que le processus de démarrage n\'est pas en cours sur le scanneur.	Terminez la modification des paramètres du scanneur.	Connectez un seul scanneur à l\'ordinateur.	Quittez l\'autre application qui utilise actuellement le scanneur.	Vérifiez les modèles de scanneurs pris en charge par l\'Outil d\'enregistrement de certificats.	Pour en savoir plus, reportez-vous à la rubrique 	Modèles de scanneurs pris en charge.	Si un message reste affiché après la prise des mesures ci-dessus, procédez comme suit :	Éteignez le scanneur, puis rallumez-le.	CONSEIL	Lorsque vous essayez d\'éteindre le scanneur, le message "En cours de fonctionnement..." peut rester affiché sur l\'écran tactile du scanneur. Même si cela se produit, l\'extinction du scanneur ne devrait pas être un problème.	Redémarrez le scanneur.	Redémarrez l\'Outil d\'enregistrement de certificats.'];
searchDatas1[68] = ['','Échec de l\'obtention des informations du certificat.','./tb_cer_02.html', '	Échec de l\'obtention des informations du certificat.	Cause 	Vous avez effectué les opérations suivantes après avoir cliqué sur le bouton [Configurer] dans la 	Fenêtre [Outil d\'enregistrement de certificats].	Mise hors tension du scanneur	Connexion et déconnexion du scanneur de l\'ordinateur avec le câble USB	Solution 	Procédez comme suit :	Mettez le scanneur sous tension.	Reliez le scanneur à l\'ordinateur à l\'aide du câble USB fourni avec le scanneur.	Redémarrez l\'Outil d\'enregistrement de certificats.	Si un message reste affiché après la prise des mesures ci-dessus, procédez comme suit :	Éteignez le scanneur, puis rallumez-le.	CONSEIL	Lorsque vous essayez d\'éteindre le scanneur, le message "En cours de fonctionnement..." peut rester affiché sur l\'écran tactile du scanneur. Même si cela se produit, l\'extinction du scanneur ne devrait pas être un problème.	Redémarrez le scanneur.	Redémarrez l\'Outil d\'enregistrement de certificats.'];
searchDatas1[69] = ['','Échec de la suppression du certificat.','./tb_cer_04.html', '	Échec de la suppression du certificat.	Cause 	Vous avez effectué les opérations suivantes après avoir cliqué sur le bouton [Configurer] dans la 	Fenêtre [Outil d\'enregistrement de certificats].	Mise hors tension du scanneur	Connexion et déconnexion du scanneur de l\'ordinateur avec le câble USB	Solution 	Procédez comme suit :	Mettez le scanneur sous tension.	Reliez le scanneur à l\'ordinateur à l\'aide du câble USB fourni avec le scanneur.	Redémarrez l\'Outil d\'enregistrement de certificats.	Si un message reste affiché après la prise des mesures ci-dessus, procédez comme suit :	Éteignez le scanneur, puis rallumez-le.	CONSEIL	Lorsque vous essayez d\'éteindre le scanneur, le message "En cours de fonctionnement..." peut rester affiché sur l\'écran tactile du scanneur. Même si cela se produit, l\'extinction du scanneur ne devrait pas être un problème.	Redémarrez le scanneur.	Redémarrez l\'Outil d\'enregistrement de certificats.'];
searchDatas1[70] = ['','Échec de l\'enregistrement du certificat.','./tb_cer_05.html', '	Échec de l\'enregistrement du certificat.	Cause 	Les origines du problème peuvent être les suivantes :	Le format du certificat spécifié est incorrect	Le chargement du certificat spécifié a échoué	Vous avez effectué les opérations suivantes après avoir cliqué sur le bouton [Configurer] dans la 	Fenêtre [Outil d\'enregistrement de certificats]	Mise hors tension du scanneur	Connexion et déconnexion du scanneur de l\'ordinateur avec le câble USB	Solution 	Procédez comme suit :	Vérifiez que le format du certificat est correct.	Les certificats pouvant être enregistrés sont les suivants :	Certificats client: fichier au format PKCS#12 (*.p12, *.pfx)	Certificats CA: fichier de certificat CA (*.cer, *.crt, *.der, *.pem)	Vérifiez que vous disposez de privilèges d\'accès au fichier de certificat.	Mettez le scanneur sous tension.	Reliez le scanneur à l\'ordinateur à l\'aide du câble USB fourni avec le scanneur.	Redémarrez l\'Outil d\'enregistrement de certificats.	Si un message reste affiché après la prise des mesures ci-dessus, procédez comme suit :	Éteignez le scanneur, puis rallumez-le.	CONSEIL	Lorsque vous essayez d\'éteindre le scanneur, le message "En cours de fonctionnement..." peut rester affiché sur l\'écran tactile du scanneur. Même si cela se produit, l\'extinction du scanneur ne devrait pas être un problème.	Redémarrez le scanneur.	Redémarrez l\'Outil d\'enregistrement de certificats.'];
searchDatas1[71] = ['','Mot de passe incorrect.','./tb_cer_06.html', '	Mot de passe incorrect.	Cause 	Le mot de passe que vous avez saisi est incorrect.	Solution 	Saisissez le mot de passe correct.	Il est possible d\'utiliser les caractères suivants pour votre mot de passe.	Caractères alphanumériques	A à Z, a à z, 0 à 9	Symboles	! " # $ % & \' ( ) * + , - . / : ; < = > ? @ [ 	\\ ] ^ _ ` { | } ~	Espaces'];
searchDatas1[72] = ['','Button Event Manager','./tb_bem.html', '	Button Event Manager	Cette section décrit les messages d\'erreur susceptibles de s\'afficher lors de l\'utilisation de Button Event Manager, et explique comment résoudre ces erreurs. 	Échec du traitement suite à une erreur inattendue.	Aucun fichier d\'aide trouvé.	'];
searchDatas1[73] = ['','Échec du traitement suite à une erreur inattendue.','./tb_bem_01.html', '	Échec du traitement suite à une erreur inattendue.	Cause 	Une erreur inattendue est survenue.	Solution 	Redémarrez l\'ordinateur, puis redémarrez Button Event Manager.'];
searchDatas1[74] = ['','Aucun fichier d\'aide trouvé.','./tb_bem_02.html', '	Aucun fichier d\'aide trouvé.	Cause 	Le fichier d\'aide n\'existe pas.	Solution 	Désinstallez l\'application Network Setup Tool for fi Series, puis réinstallez-la.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.'];
searchDatas1[75] = ['','Dépannage','./title_trouble.html', '	Dépannage	Cette section décrit les problèmes susceptibles de survenir lors de l\'utilisation de Network Setup Tool for fi Series, et explique comment résoudre ces problèmes. 	Aucun scanneur trouvé	Impossible de lancer une numérisation en appuyant sur la touche du scanneur	'];
searchDatas1[76] = ['','Aucun scanneur trouvé','./trouble_01.html', '	Aucun scanneur trouvé	Vérifiez les éléments suivants : 	La méthode de connexion (utilisée pour connecter le scanneur) est-elle différente de celle définie dans les paramètres du scanneur ? (fi-7300NX)	Les paramètres du scanneur sont-ils correctement configurés ?	Le processus de démarrage ou d\'initialisation est-il en cours d\'exécution sur le scanneur ?	Est-ce qu\'une autre application utilise le scanneur ?	Les paramètres réseau de l\'ordinateur sont-ils correctement configurés ?	Le système d\'exploitation de l\'ordinateur est-il en cours de mise à jour ou en attente de redémarrage ?	Le scanneur est-il connecté au même sous-réseau que votre ordinateur ?	Les paramètres des périphériques réseau (commutateur, concentrateur ou routeur) sont-ils corrects ?	L\'état de la communication entre le scanneur et l\'ordinateur est-il stable ?	Si un scanneur est introuvable après avoir pris les mesures ci-dessus, redémarrez le scanneur et l\'ordinateur, puis redémarrez l\'Outil de sélection du scanneur.	Si le scanneur n\'apparaît pas dans l\'application de numérisation d\'image, consultez la rubrique 	Impossible de lancer une numérisation depuis l\'application de numérisation d\'image.	La méthode de connexion (utilisée pour connecter le scanneur) est-elle différente de celle définie dans les paramètres du scanneur ? (fi-7300NX)	Solution 	Vérifiez que le réseau Wi-Fi ou le réseau LAN câblé est configuré comme méthode de connexion du scanneur.	Pour cela, procédez comme suit.	Sur l\'écran tactile du scanneur, appuyez sur 	 	→ [Paramètres du scanneur] 	→ [Méthode de connexion].	Les paramètres du scanneur sont-ils correctement configurés ?	Solution 	Pour fi-8040 ou fi-7300NX	Vérifiez les paramètres réseau du scanneur.	Pour cela, procédez comme suit.	Sur l\'écran tactile du scanneur, appuyez sur 	 	→ [Paramètres du scanneur] 	→ [Réseau].	Pour fi-8950, fi-8930, fi-8820, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150 ou fi-8250	Utilisez l\'Outil de configuration de l\'adresse IP pour vérifier les paramètres réseau du scanneur.	Pour en savoir plus sur la façon de démarrer l\'Outil de configuration de l\'adresse IP, consultez la section 	Démarrage de l\'Outil de configuration de l\'adresse IP.	Le processus de démarrage ou d\'initialisation est-il en cours d\'exécution sur le scanneur ?	Solution 	Vérifiez que le processus de démarrage ou d\'initialisation n\'est pas en cours sur le scanneur.	Pour en savoir plus, consultez le Guide d\'utilisation du scanneur.	Est-ce qu\'une autre application utilise le scanneur ?	Solution 	Quittez l\'autre application qui utilise actuellement le scanneur.	Les paramètres réseau de l\'ordinateur sont-ils correctement configurés ?	Solution 	Vérifiez les paramètres réseau de l\'ordinateur.	Pour en savoir plus sur la configuration des paramètres réseau de l\'ordinateur, consultez le guide de votre ordinateur.	Le système d\'exploitation de l\'ordinateur est-il en cours de mise à jour ou en attente de redémarrage ?	Solution 	Redémarrez l\'Outil de sélection du scanneur après la mise à jour du système d\'exploitation ou le redémarrage de l\'ordinateur.	Le scanneur est-il connecté au même sous-réseau que votre ordinateur ?	Même si le scanneur est connecté au même sous-réseau que votre ordinateur, il peut être introuvable.	Solution 	Sélectionnez [Rechercher à partir de l\'adresse IP du scanneur] dans la 	Fenêtre [Outil de sélection du scanneur], puis saisissez l\'adresse IP du scanneur.	Les paramètres des périphériques réseau (commutateur, concentrateur ou routeur) sont-ils corrects ?	Solution 	Vérifiez les paramètres des périphériques réseau (commutateur, concentrateur ou routeur).	Pour en savoir plus sur la définition du périphérique réseau, consultez le guide de votre périphérique réseau.	L\'état de la communication entre le scanneur et l\'ordinateur est-il stable ?	Solution 	Pour fi-8040 ou fi-7300NX	Vérifiez l\'état de la communication entre le scanneur et l\'ordinateur.	Vous pouvez vérifier l\'état de la communication entre le scanneur et l\'ordinateur sur l\'écran tactile du scanneur.	Pour cela, procédez comme suit.	Sur l\'écran tactile du scanneur, appuyez sur 	 	→ [Paramètres du scanneur] 	→ [Réseau] 	→ [Vérifier la connexion (Ping)].	Pour fi-8950, fi-8930, fi-8820, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150 ou fi-8250	Vérifiez l\'état de la communication entre le scanneur et l\'ordinateur.	Démarrez l\'invite de commandes sur votre ordinateur et exécutez la commande ping pour vérifier l\'état de communication en spécifiant l\'adresse IP du scanneur.	Utilisez l\'Outil de configuration de l\'adresse IP pour vérifier l\'adresse IP du scanneur.	Pour en savoir plus sur la façon de démarrer l\'Outil de configuration de l\'adresse IP, consultez la section 	Démarrage de l\'Outil de configuration de l\'adresse IP.'];
searchDatas1[77] = ['','Impossible de lancer une numérisation en appuyant sur la touche du scanneur','./trouble_02.html', '	Impossible de lancer une numérisation en appuyant sur la touche du scanneur	Vérifiez les éléments suivants : 	Le scanneur est-il sélectionné dans l\'Outil de sélection du scanneur ?	Button Event Manager a-t-il démarré ?	L\'option [Afficher l\'événement de bouton] est-elle sélectionnée dans le menu de Button Event Manager ?	Les paramètres de la touche du scanneur sont-ils corrects ?	Le scanneur est-il utilisé par un autre ordinateur ?	Le scanneur est-il sélectionné dans l\'Outil de sélection du scanneur ?	Solution 	Dans la 	Fenêtre [Outil de sélection du scanneur], vérifiez que le scanneur est sélectionné.	Button Event Manager a-t-il démarré ?	Solution 	Vérifiez que Button Event Manager a démarré.	Une fois que Button Event Manager a démarré, 	 apparaît dans la zone de notification située à l\'extrémité droite de la barre des tâches.	Pour en savoir plus sur la façon de démarrer Button Event Manager, consultez la section 	Démarrage de Button Event Manager.	L\'option [Afficher l\'événement de bouton] est-elle sélectionnée dans le menu de Button Event Manager ?	Solution 	Démarrez Button Event Manager et cliquez avec le bouton droit sur 	 dans la zone de notification située à l\'extrémité droite de la barre des tâches pour afficher la 	Menu de Button Event Manager. Vérifiez que l\'option [Afficher l\'événement de bouton] est sélectionnée.	Pour en savoir plus sur la façon de démarrer Button Event Manager, consultez la section 	Démarrage de Button Event Manager.	Les paramètres de la touche du scanneur sont-ils corrects ?	Solution 	Dans la 	Fenêtre [Paramètres du bouton] de Button Event Manager, vérifiez que le paramètre de la touche est correct.	Vérifiez que l\'application de numérisation d\'image que vous avez attribuée à la touche du scanneur est exécutée sur l\'ordinateur.	Le scanneur est-il utilisé par un autre ordinateur ?	Solution 	Lorsque le même scanner a été sélectionné par plusieurs ordinateurs à l\'aide de l\'outil de sélection du scanneur, sélectionnez [Afficher l\'événement de bouton] dans le menu de Button Event Manager uniquement sur l\'ordinateur avec lequel vous souhaitez utiliser le scanner.	Si vous ne parvenez pas à lancer une numérisation après avoir pris les mesures ci-dessus, procédez comme suit :	Quittez l\'application de numérisation d\'images qui se trouve dans la zone de notification située à l\'extrême droite de la barre des tâches	Éteignez le scanneur, puis rallumez-le'];
searchDatas1[78] = ['','Modèles de scanneurs pris en charge','./support.html', '	Modèles de scanneurs pris en charge	Les modèles de scanneurs pris en charge par Network Setup Tool for fi Series sont les suivants. 	Outil de sélection du scanneur	fi-8950, fi-8930, fi-8820, fi-8040, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150, fi-8250, fi-7300NX	Outil de configuration de l\'adresse IP	fi-8950, fi-8930, fi-8820, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150, fi-8250	Outil d\'enregistrement de certificats	fi-7300NX	Button Event Manager	fi-8950, fi-8930, fi-8820, fi-8040, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150, fi-8250, fi-7300NX'];
searchDatas1[79] = ['','Impossible de lancer une numérisation depuis l\'application de numérisation d\'image','./trouble_04.html', '	Impossible de lancer une numérisation depuis l\'application de numérisation d\'image	Vérifiez les éléments suivants : 	Avez-vous configuré un serveur proxy lors de la configuration du proxy WinHTTP ?	Avez-vous configuré un serveur proxy lors de la configuration du proxy WinHTTP ?	Solution 	Modifiez les paramètres du proxy WinHTTP de façon à pouvoir accéder au scanneur depuis l\'ordinateur.	Procédez comme suit pour modifier les paramètres du proxy WinHTTP.	Ouvrez la fenêtre d\'invite de commande en tant qu\'utilisateur doté de privilèges d\'administrateur sur l\'ordinateur.	Exécutez la commande suivante pour vérifier le nom du serveur proxy et les numéros de port à utiliser.	netsh winhttp show proxy	CONSEIL	Le nom du serveur proxy et les numéros de port à utiliser s\'affichent comme suit.	"Nom du serveur proxy : Numéros de port"	Exécutez l\'une des commandes suivantes.	Si un serveur proxy a déjà été configuré	Configurez ce paramètre de façon à ce que l\'ordinateur puisse accéder au scanneur sans utiliser le serveur proxy.	netsh winhttp set proxy proxy-server="XXXXXX:YYYY" bypass-list=ZZZ.ZZZ.ZZZ.ZZZ	XXXXXX : nom du serveur proxy	YYYY : numéros de port à utiliser	ZZZ.ZZZ.ZZZ.ZZZ : adresse IP du scanneur (*1)(*2)	Si aucun serveur proxy n\'a été configuré	Réinitialisez les paramètres pour que l\'ordinateur puisse accéder au scanneur.	netsh winhttp reset proxy	*1 :	vous pouvez vérifier l\'adresse IP du scanneur sur l\'écran tactile ou sur le panneau de commande du scanneur, ou dans l\'Outil de configuration de l\'adresse IP.	*2 :	Le format d\'adresse IPv4 est utilisé ici à titre d\'exemple.	Pour une adresse IPv6, le format suivant est utilisé.	ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ'];
searchDatas1[80] = ['','Mot de passe de l\'administrateur d\'un scanneur','./adminpassword.html', '	Mot de passe de l\'administrateur d\'un scanneur	Pour en savoir plus sur le mot de passe de l\'administrateur par défaut défini en usine, reportez-vous au Guide d\'utilisation du scanneur.'];
